# owner: platform
"""Snap span times to a fixed step for payroll."""

from hourglass.models import Span


def _snap(value: int, step: int) -> int:
    return (value + step // 2) // step * step


def _clock(value: int) -> str:
    return f"{value // 60:02d}:{value % 60:02d}"


# ---
def round_labels(spans: list[Span], step: int) -> list[str]:
    """Round each span to the step; label like 09:00-17:15 (8h 15m)."""
    if step <= 0 or 60 % step:
        raise ValueError(f"bad step: {step}")
    labels = []
    for span in spans:
        start = _snap(span.start, step)
        end = _snap(span.end, step)
        hours, mins = divmod(Span(start, end).minutes, 60)
        labels.append(
            f"{_clock(start)}-{_clock(end)} ({hours}h {mins}m)"
        )
    return labels
EOF
