    def test_halfway_rounds_up(self):
        self.assertEqual(
            round_labels([Span(7, 60)], 15),
            ["00:15-01:00 (0h 45m)"]
        )

    def test_bad_steps(self):
        for step in (0, -5, 7, 45):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)
